// Shared DataGrid shell.
// Every data-column Title is generated by the canonical
// Title infrastructure; DataGrid only owns split header/body scrolling + geometry sync.

import { hydrateCanonicalColumnTitles } from "./column_schemas.js";
import { pinWidth } from "./column_title.js";
import { RowSnapController, RowStopController, enableRowUnitScroll } from "./row_snap.js";
import { DiscreteRowScrollbarController } from "./discrete_row_scrollbar.js";
import { mountHorizontalRail } from "./horizontal_rail.js";
//
// Visual/DOM contract (same idea as 商品頁 -> 查詢商品):
//   [header table - never scrolls vertically]
//   [body scroll viewport - owns vertical/horizontal scrollbar]
//
// The original table remains the header table so canonical Title sort/resize
// bindings keep the same scoped table instance. The original <tbody> is moved
// into a second body table.  A single synchronizer mirrors column geometry from
// header -> body and horizontal scroll from body -> header.

const GRID_RULES = [
  // width "fill": the table fills its wrapper (its stylesheet says width 100%); the grid writes that, never a px width
  // a stylesheet would then have to override with !important.
  // The product lists keep each column's minimum width (column_title.js keepMinimums): more columns than the pane
  // holds scroll sideways rather than cutting numbers, with a visible rail (xRail: their native scrollbars are hidden
  // for the row rail).
  { selector: ".product-list-table-wrap", x: "auto", width: "fill", xRail: true },
  { selector: ".event-feed-table-wrap", x: "auto" },
  { selector: ".tick-details .tick-table-wrap", x: "hidden" },
  { selector: ".trade-details-table-wrap", x: "auto" },
  { selector: ".account-page .finance-table-wrap", x: "auto", width: "fill" },
  // Final catch-all: every ordinary table-wrap with a real thead/tbody uses the
  // same template. upgradeStandardDataGrid safely skips non-table wrappers.
  { selector: ".table-wrap", x: "auto" },
  { selector: ".tick-table-wrap", x: "auto" },
];
const GRID_WRAPPER_SELECTOR = GRID_RULES.map((rule) => rule.selector).join(", ");

// ISSUE 021 scroll recovery: StandardDataGrid is stateful and touches shared DOM.
// ES module query strings are part of module identity; historically the renderer
// imported data_grid.js through several different ?v=... URLs.  That created
// multiple GRID_STATE WeakMaps and observers.  One instance could see another
// instance's data-standard-data-grid-ready marker without owning its WeakMap
// state, tear the shell down, and rebuild it while TickDetails was already
// bound to the previous bodyScroll.  The visible result is a trade-detail rail
// that looks mounted but no longer scrolls.
//
// Keep the runtime on globalThis so even an accidental duplicate module URL
// shares the same DOM ownership.  Import specifiers are also normalized by the
// ISSUE 021 patch, but this guard makes the singleton invariant durable.
const DATA_GRID_RUNTIME_KEY = Symbol.for("shioaji.renderer.standardDataGridRuntime.v1");
const DATA_GRID_RUNTIME = globalThis[DATA_GRID_RUNTIME_KEY] || (globalThis[DATA_GRID_RUNTIME_KEY] = {
  gridState: new WeakMap(),
  observer: null,
  observerRoot: null,
  nextGridId: 0,
});
const GRID_STATE = DATA_GRID_RUNTIME.gridState;

const COLUMN_RESIZER_SELECTOR = '[data-column-boundary][data-column-resizable="1"]';

// Only fixed-row long tables opt in. Expandable/grouped tables
// deliberately stay out because a single row-height contract would be incorrect.
const ROW_SNAP_GRID_SELECTORS = [
  ".account-trades-wrap",
  ".account-daytrade-bucket-detail-wrap",
  ".account-daytrade-weekday-detail-wrap",
];

function rowSnapEnabled(wrapper) {
  if (wrapper?.dataset?.rowSnap === "1") return true;
  if (wrapper?.dataset?.rowSnap === "0") return false;
  return ROW_SNAP_GRID_SELECTORS.some((selector) => wrapper?.matches?.(selector));
}

function ensureGridRowSnap(state) {
  if (!state || !rowSnapEnabled(state.wrapper)) return state?.rowSnap || null;
  // A component may explicitly destroy its controller while the DataGrid shell
  // survives for hydration. Never return that detached controller on remount.
  if (state.rowSnap?.viewport) return state.rowSnap;
  if (state.rowSnap && !state.rowSnap.viewport) state.rowSnap = null;
  const wrapper = state.wrapper;
  wrapper.dataset.rowSnap = "1";
  state.bodyScroll.classList.add("shared-row-snap-scroll");
  const options = {
    viewport: state.bodyScroll,
    rowSelector: "tbody tr",
    rowHeightVar: String(wrapper.dataset.rowSnapHeightVar || "--row-height-data-grid"),
    smooth: wrapper.dataset.rowSnapSmooth === "1",
    maskRemainder: wrapper.dataset.rowSnapMask !== "0",
    wheelStepRows: Math.max(1, Number(wrapper.dataset.rowSnapWheelRows) || 1),
    measureActualRow: wrapper.dataset.rowSnapMeasureActual === "1",
    fitViewportRows: wrapper.dataset.rowSnapFitViewport === "1",
    distributeRemainder: wrapper.dataset.rowSnapDistributeRemainder === "1",
    minRowHeightVar: String(wrapper.dataset.rowSnapMinHeightVar || ""),
    maxRowHeightVar: String(wrapper.dataset.rowSnapMaxHeightVar || ""),
    // DataGrid already owns the canonical resize observer below. Do not mount a
    // second viewport observer inside RowSnapController.
    observeResize: false,
  };
  state.rowSnap = wrapper.dataset.rowSnapUnit === "1"
    ? enableRowUnitScroll(options)
    : new RowSnapController(options).mount();

  if (wrapper.dataset.rowSnapDiscreteRail === "1") {
    wrapper.dataset.standardGridDiscreteRail = "1";
    let railHost = wrapper.querySelector(":scope > .shared-discrete-row-rail");
    if (!railHost) {
      railHost = document.createElement("div");
      railHost.className = "shared-discrete-row-rail";
      railHost.setAttribute("aria-hidden", "false");
      wrapper.appendChild(railHost);
    }
    const syncGeometry = () => {
      const headerHeight = Math.max(0, Math.round(state.headerBand?.getBoundingClientRect?.().height || 0));
      railHost.style.top = `${headerHeight}px`;
    };
    syncGeometry();
    state.discreteRowScrollbar?.destroy?.();
    const scrollbar = new DiscreteRowScrollbarController({
      host: railHost,
      viewport: state.bodyScroll,
    }).mount();
    state.discreteRowScrollbar = scrollbar;
    const observer = typeof ResizeObserver === "function" ? new ResizeObserver(syncGeometry) : null;
    observer?.observe?.(wrapper);
    observer?.observe?.(state.headerBand);
    // This mount owns its rail, scrollbar and the wrapper flag that positions the rail. A list keeps its controller
    // after the grid tore it down and mounted a new one, so destroy acts once: a second call would take the flag off
    // the newer rail and drop it out of its absolute place.
    const rowSnap = state.rowSnap;
    const originalDestroy = rowSnap.destroy.bind(rowSnap);
    let destroyed = false;
    rowSnap.destroy = () => {
      if (destroyed) return;
      destroyed = true;
      observer?.disconnect?.();
      scrollbar.destroy();
      if (state.discreteRowScrollbar === scrollbar) state.discreteRowScrollbar = null;
      railHost.remove();
      wrapper.removeAttribute("data-standard-grid-discrete-rail");
      originalDestroy();
    };
  }
  return state.rowSnap;
}

// Canonical entry point for fixed-height scrolling tables. Components bind to
// DataGrid's real inner viewport, not the outer shell replaced by the split.
export function enableDataGridRowSnap(wrapper, {
  rowHeightVar = "--row-height-data-grid",
  smooth = false,
  maskRemainder = false,
  rowUnit = false,
  wheelStepRows = 1,
  discreteRail = false,
  measureActualRow = false,
  fitViewportRows = false,
  distributeRemainder = false,
  minRowHeightVar = "",
  maxRowHeightVar = "",
  gridOptions = null,
} = {}) {
  if (!wrapper) return null;
  wrapper.dataset.rowSnap = "1";
  wrapper.dataset.rowSnapHeightVar = String(rowHeightVar);
  wrapper.dataset.rowSnapSmooth = smooth ? "1" : "0";
  wrapper.dataset.rowSnapMask = maskRemainder ? "1" : "0";
  wrapper.dataset.rowSnapUnit = rowUnit ? "1" : "0";
  wrapper.dataset.rowSnapWheelRows = String(Math.max(1, Math.trunc(Number(wheelStepRows) || 1)));
  wrapper.dataset.rowSnapDiscreteRail = discreteRail ? "1" : "0";
  wrapper.dataset.rowSnapMeasureActual = measureActualRow ? "1" : "0";
  wrapper.dataset.rowSnapFitViewport = fitViewportRows ? "1" : "0";
  wrapper.dataset.rowSnapDistributeRemainder = distributeRemainder ? "1" : "0";
  wrapper.dataset.rowSnapMinHeightVar = String(minRowHeightVar || `${rowHeightVar}-min`);
  wrapper.dataset.rowSnapMaxHeightVar = String(maxRowHeightVar || `${rowHeightVar}-max`);
  return ensureGridRowSnap(upgradeStandardDataGrid(wrapper, gridOptions));
}

// Canonical entry point for every fixed-height user-facing row list.  Product
// rows, live/history events, live/history ticks and trade records all use this
// exact contract:
//   scrollTop / measuredRowPitch -> logical first-row index
//   logical index * measuredRowPitch -> the only valid resting scrollTop
// The body viewport keeps its full panel height. The real horizontal-scrollbar
// lane is removed from the row budget and any remaining pixels are distributed
// across whole rows within min/max bounds, so no row is clipped and no dead
// blank strip remains below the data.
export function enableCompleteRowDataGridScroll(wrapper, {
  rowHeightVar = "--row-height-data-grid",
  wheelStepRows = 1,
  discreteRail = false,
  minRowHeightVar = "",
  maxRowHeightVar = "",
  gridOptions = null,
} = {}) {
  if (!wrapper) return { grid: null, rowSnap: null, viewport: null };
  const rowSnap = enableDataGridRowSnap(wrapper, {
    rowHeightVar,
    smooth: false,
    maskRemainder: false,
    rowUnit: true,
    wheelStepRows,
    discreteRail,
    measureActualRow: false,
    fitViewportRows: true,
    distributeRemainder: true,
    minRowHeightVar: minRowHeightVar || `${rowHeightVar}-min`,
    maxRowHeightVar: maxRowHeightVar || `${rowHeightVar}-max`,
    gridOptions,
  });
  const grid = GRID_STATE.get(wrapper) || null;
  return {
    grid,
    rowSnap,
    viewport: grid?.bodyScroll || wrapper,
  };
}

function nextGridId() {
  DATA_GRID_RUNTIME.nextGridId += 1;
  return `standard-data-grid-${DATA_GRID_RUNTIME.nextGridId}`;
}

function directTable(wrapper) {
  return [...wrapper.children].find((child) => child?.tagName === "TABLE") || null;
}

function resolveOptions(wrapper) {
  // A table that must never scroll horizontally says so (replay events, trade details).
  if (wrapper.dataset.gridX === "hidden") {
    return { x: "hidden" };
  }
  for (const rule of GRID_RULES) {
    if (wrapper.matches(rule.selector)) return { ...rule };
  }
  return null;
}

function copyColumnNode(source, target) {
  target.className = source.className;
  target.style.cssText = source.style.cssText;
  for (const attr of ["width", "span"]) {
    if (source.hasAttribute(attr)) target.setAttribute(attr, source.getAttribute(attr));
    else target.removeAttribute(attr);
  }
}

function ensureBodyColgroup(state, sourceCols, measuredWidths) {
  let group = state.bodyTable.querySelector(":scope > colgroup[data-standard-grid-body-cols]");
  if (!group) {
    group = document.createElement("colgroup");
    group.dataset.standardGridBodyCols = "1";
    state.bodyTable.insertBefore(group, state.bodyTable.firstChild);
  }

  const count = sourceCols.length || measuredWidths.length;
  while (group.children.length < count) group.appendChild(document.createElement("col"));
  while (group.children.length > count) group.lastElementChild?.remove();

  // Whole pixels that add up to the titles' own total: each column is rounded at its right edge, not on its own
  // (seven 147.7 px columns rounded one by one are 2 px wider than the titles, and the rows scroll sideways).
  let edge = 0;
  const pixelWidths = Array.from({ length: count }, (_, index) => {
    const left = Math.round(edge);
    edge += Number(measuredWidths[index]) || 1;
    return Math.round(edge) - left;
  });

  [...group.children].forEach((target, index) => {
    const source = sourceCols[index];
    const measuredWidth = Math.max(1, pixelWidths[index]);
    if (source) {
      copyColumnNode(source, target);
      // The visible canonical Title is the source of truth. Column resize
      // mutates its canonical colgroup; after browser layout, mirror the
      // *actual rendered width* to the body colgroup so rows move with Title
      // continuously even when the source width is expressed as %, calc(),
      // or is constrained by a neighboring column.
      pinWidth(target, measuredWidth);
    } else {
      target.className = "";
      target.removeAttribute("width");
      target.removeAttribute("span");
      target.style.cssText = "";
      pinWidth(target, measuredWidth);
    }
  });
}

function headerCells(state) {
  const rows = [...state.headerTable.querySelectorAll(":scope > thead > tr")];
  const row = rows.at(-1);
  return row ? [...row.children].filter((cell) => cell.tagName === "TH" || cell.tagName === "TD") : [];
}

function sourceColumns(state) {
  const groups = [...state.headerTable.querySelectorAll(":scope > colgroup")];
  if (!groups.length) return [];
  // Prefer the canonical schema colgroup: DataGrid does not
  // maintain a separate legacy Header/column-geometry source.
  const preferred = groups.find((group) => group.hasAttribute("data-column-schema-owner"))
    || groups[0];
  return [...preferred.querySelectorAll(":scope > col")];
}

function copyTableGeometry(state, measuredWidths = []) {
  const headerRect = state.headerTable.getBoundingClientRect();
  const cols = sourceColumns(state);
  const measuredTotal = measuredWidths.reduce((sum, value) => sum + (Number(value) || 0), 0);
  // When there is a 1:1 header cell/column mapping, use the rendered Title
  // geometry itself as body width. This keeps every vertical divider on the
  // exact same x coordinate instead of letting the two tables redistribute a
  // spare border pixel differently.
  const canUseMeasuredTotal = measuredTotal > 0 && cols.length === measuredWidths.length;
  const width = Math.max(
    1,
    canUseMeasuredTotal ? Math.ceil(measuredTotal) : 0,
    canUseMeasuredTotal ? 0 : Math.ceil(state.headerTable.scrollWidth || 0),
    canUseMeasuredTotal ? 0 : Math.ceil(headerRect.width || 0),
    canUseMeasuredTotal ? 0 : Math.ceil(state.headerViewport.clientWidth || 0),
  );

  if (state.options?.width === "fill") pinWidth(state.bodyTable, "100%", { min: 0, max: "100%" });
  else pinWidth(state.bodyTable, width, { max: "none" });
}

function syncColumnsNow(state) {
  if (!state?.wrapper?.isConnected) return;
  const cells = headerCells(state);
  if (!cells.length) return;

  const measured = cells.map((cell) => Math.max(1, cell.getBoundingClientRect().width || 1));
  const cols = sourceColumns(state);
  ensureBodyColgroup(state, cols, measured);
  copyTableGeometry(state, measured);

  // Horizontal position is owned by the body viewport.  The header viewport is
  // overflow:hidden but remains programmatically scrollable.
  state.headerViewport.scrollLeft = state.bodyScroll.scrollLeft;
  updateScrollbarLane(state);
}

function scheduleSync(state) {
  if (!state || state.syncFrame) return;
  state.syncFrame = requestAnimationFrame(() => {
    state.syncFrame = 0;
    syncColumnsNow(state);
  });
}

function mutationChangesRowTopology(records = []) {
  const touchesRow = (node) => node?.nodeType === 1 && (
    node.matches?.("tr")
    || Boolean(node.querySelector?.("tr"))
  );
  return records.some((record) => {
    if (record.type !== "childList") return false;
    if (record.target?.tagName === "TBODY") {
      return [...record.addedNodes, ...record.removedNodes].some(touchesRow);
    }
    return [...record.addedNodes, ...record.removedNodes].some(touchesRow);
  });
}

// The Title's scrollbar-cap lane: as wide as the body's vertical scrollbar (its colours are the title cells' own
// tokens in data-grid.css). A grid whose rail is the in-body overlay (TickDetails) never reserves the native
// scrollbar, so it reads no geometry at all.
function updateScrollbarLane(state) {
  if (!state?.bodyScroll?.isConnected) return;
  const overlayScrollbar = state.wrapper?.dataset?.standardGridOverlayScrollbar === "1";
  const reservedLane = overlayScrollbar ? 0 : Math.max(0, Number(state.wrapper?.dataset?.scrollbarLaneMin) || 0);
  let measuredLane = 0;
  if (!overlayScrollbar) {
    const vertical = state.bodyScroll.scrollHeight > state.bodyScroll.clientHeight + 1;
    measuredLane = vertical ? Math.max(0, Math.round(state.bodyScroll.offsetWidth - state.bodyScroll.clientWidth)) : 0;
  }
  const lane = Math.max(measuredLane, reservedLane);
  if (state.scrollbarLane !== lane) {
    state.scrollbarLane = lane;
    state.headerBand.style.setProperty("--standard-grid-scrollbar-lane", `${lane}px`);
  }
}

function teardownGridState(wrapper) {
  const state = GRID_STATE.get(wrapper);
  if (state?.syncFrame) cancelAnimationFrame(state.syncFrame);
  if (state?.liveResizeFrame) cancelAnimationFrame(state.liveResizeFrame);
  state?.stopLiveResizeSync?.();
  state?.resizeObserver?.disconnect?.();
  state?.bodyHeightObserver?.disconnect?.();
  state?.headerObserver?.disconnect?.();
  state?.bodyObserver?.disconnect?.();
  state?.rowSnap?.destroy?.();
  state?.rowStops?.destroy?.();
  state?.xRail?.destroy?.();
  GRID_STATE.delete(wrapper);
  delete wrapper.dataset.standardDataGridReady;
  delete wrapper.dataset.standardGridX;
  delete wrapper.dataset.standardGridTitleSource;
  wrapper.classList.remove("standard-data-grid");
}

// Cached pages hydrate the same DOM on their next mount. Restore the original
// single table as well as releasing observers, so the next upgrade can split
// its header and body again.
export function destroyStandardDataGrid(wrapper) {
  if (!wrapper) return;
  const state = GRID_STATE.get(wrapper);
  teardownGridState(wrapper);
  if (!state || state.headerBand.parentElement !== wrapper || state.bodyScroll.parentElement !== wrapper) return;
  const table = state.headerTable;
  const sections = [...state.bodyTable.children].filter(node => ["TBODY", "TFOOT"].includes(node.tagName));
  table.append(...sections);
  table.classList.remove("standard-data-grid-header-table");
  delete table.dataset.standardGridHeaderTable;
  delete table.dataset.standardGridId;
  const siblings = [...wrapper.children].filter(node => node !== state.headerBand && node !== state.bodyScroll);
  wrapper.replaceChildren(table, ...siblings);
}

function buildBodyTable(headerTable, tbody, tfoot) {
  const bodyTable = document.createElement("table");
  bodyTable.className = `${headerTable.className} standard-data-grid-body-table`.trim();
  bodyTable.dataset.standardGridBodyTable = "1";
  bodyTable.removeAttribute("id");
  bodyTable.removeAttribute("aria-describedby");
  bodyTable.removeAttribute("aria-labelledby");
  bodyTable.appendChild(tbody);
  if (tfoot) bodyTable.appendChild(tfoot);
  return bodyTable;
}

// An already standardized wrapper: its state when the shell is still in place, else null after clearing the stale
// ready flag (some dynamic account sections replace wrapper.innerHTML -- the wrapper survives but our shell does not).
function reuseReadyGrid(wrapper) {
  if (wrapper.dataset.standardDataGridReady !== "1") return null;
  const state = GRID_STATE.get(wrapper);
  const shellStillValid = Boolean(
    state
    && state.headerBand?.isConnected
    && state.bodyScroll?.isConnected
    && wrapper.querySelector(":scope > .standard-data-grid-header-band")
    && wrapper.querySelector(":scope > .standard-data-grid-body-scroll")
  );
  if (shellStillValid) {
    ensureGridRowSnap(state);
    return state;
  }
  // Some dynamic account sections replace wrapper.innerHTML.  The wrapper
  // survives but our shell does not, so clear the stale ready flag and build
  // the standard template again around the newly inserted table.
  teardownGridState(wrapper);
  return null;
}

// The split shell: a header band (header table + scrollbar cap) over a body scroll (body table).
function buildGridShell(wrapper, table, tbody, options) {
  wrapper.dataset.standardDataGridReady = "1";
  wrapper.dataset.standardGridX = options.x || "auto";
  // The wrapper is a shell from here on (.standard-data-grid): the body viewport inside it scrolls, the shell never does.
  wrapper.classList.add("standard-data-grid");

  const gridId = nextGridId();
  const originalChildren = [...wrapper.children];
  const bodyTable = buildBodyTable(table, tbody, table.querySelector(":scope > tfoot"));

  const headerBand = document.createElement("div");
  headerBand.className = "standard-data-grid-header-band";
  const headerViewport = document.createElement("div");
  headerViewport.className = "standard-data-grid-header-viewport";
  const scrollbarCap = document.createElement("div");
  scrollbarCap.className = "standard-data-grid-scrollbar-cap";
  scrollbarCap.setAttribute("aria-hidden", "true");
  const bodyScroll = document.createElement("div");
  bodyScroll.className = "standard-data-grid-body-scroll";
  bodyScroll.dataset.standardGridX = options.x || "auto";

  table.classList.add("standard-data-grid-header-table");
  table.dataset.standardGridHeaderTable = "1";
  table.dataset.standardGridId = gridId;
  bodyTable.dataset.standardGridId = gridId;

  headerViewport.appendChild(table);
  headerBand.append(headerViewport, scrollbarCap);
  bodyScroll.appendChild(bodyTable);

  // The wrappers we standardize contain only the table.  Preserve any rare
  // siblings rather than deleting them; place them after the row viewport.
  wrapper.replaceChildren(headerBand, bodyScroll, ...originalChildren.filter((node) => node !== table));

  const state = {
    wrapper,
    headerTable: table,
    bodyTable,
    headerBand,
    headerViewport,
    scrollbarCap,
    bodyScroll,
    options,
    syncFrame: 0,
    resizeObserver: null,
    headerObserver: null,
    bodyObserver: null,
    liveResizeFrame: 0,
    stopLiveResizeSync: null,
    rowSnap: null,
  };
  GRID_STATE.set(wrapper, state);

  return state;
}

// Canonical Title owns column-resize interaction. DataGrid only mirrors its geometry during an active canonical
// boundary drag so tbody follows with zero lag.
function bindLiveColumnResize(state) {
  const { wrapper, headerBand } = state;
  headerBand.addEventListener("pointerdown", (event) => {
    const handle = event.target?.closest?.(COLUMN_RESIZER_SELECTOR);
    if (!handle || !headerBand.contains(handle)) return;

    state.stopLiveResizeSync?.();
    let active = true;
    let started = false;
    const startX = event.clientX;
    const tick = () => {
      if (!active || !wrapper.isConnected) return;
      syncColumnsNow(state);
      state.liveResizeFrame = requestAnimationFrame(tick);
    };
    const start = (moveEvent) => {
      if (started || moveEvent.clientX === startX) return;
      started = true;
      state.liveResizeFrame = requestAnimationFrame(tick);
    };
    const stop = () => {
      if (!active) return;
      active = false;
      if (state.liveResizeFrame) cancelAnimationFrame(state.liveResizeFrame);
      state.liveResizeFrame = 0;
      state.stopLiveResizeSync = null;
      window.removeEventListener("pointermove", start, true);
      window.removeEventListener("pointerup", stop, true);
      window.removeEventListener("pointercancel", stop, true);
      if (started) syncColumnsNow(state);
    };
    state.stopLiveResizeSync = stop;
    window.addEventListener("pointermove", start, true);
    window.addEventListener("pointerup", stop, true);
    window.addEventListener("pointercancel", stop, true);
  }, true);

}

function observeGrid(state, tbody) {
  const { wrapper, headerViewport, bodyScroll, headerTable: table } = state;
  state.headerObserver = new MutationObserver(() => scheduleSync(state));
  state.headerObserver.observe(table, {
    subtree: true,
    childList: true,
    attributes: true,
    characterData: true,
    attributeFilter: ["style", "class", "width", "span"],
  });

  state.bodyObserver = new MutationObserver((records) => {
    // Market cells can update dozens of times per second. A value/class/text
    // mutation cannot change the fixed row-height contract, so it must not
    // trigger row measurement. Only added/removed rows (or placeholder -> real
    // row replacement) are allowed to refit the row geometry.
    const topologyChanged = mutationChangesRowTopology(records);
    const stableColumns = state.wrapper?.dataset?.standardGridStableColumns === "1";
    if (!stableColumns) scheduleSync(state);
    state.rowSnap?.refreshContent?.({
      topologyChanged,
      // tbody.rows.length is a structural count only; it does not trigger layout.
      // Passing it lets adaptive row-scroll update its logical extent without
      // re-running DOM geometry on every live Tick/quote render.
      logicalRows: topologyChanged ? (tbody.rows?.length ?? null) : null,
    });
  });
  // Row topology can only change at tbody's direct-child level. Do not observe
  // cell/text/class mutations inside each row: live quote rendering updates those
  // constantly and they cannot change the fixed row-scroll geometry.
  state.bodyObserver.observe(tbody, { childList: true });

  if (typeof ResizeObserver !== "undefined") {
    state.resizeObserver = new ResizeObserver(() => { scheduleSync(state); state.rowSnap?.scheduleMeasure?.(); });
    state.resizeObserver.observe(wrapper);
    state.resizeObserver.observe(headerViewport);
    state.resizeObserver.observe(bodyScroll);
    state.resizeObserver.observe(table);
    headerCells(state).forEach((cell) => state.resizeObserver.observe(cell));
    // Whether the body scrolls vertically changes only with the body table's height. ResizeObserver reports it
    // after layout, before paint, and only when the height really changed: a live tape that adds a row and drops
    // the oldest never fires it. A grid with the in-body overlay rail has a fixed lane and needs no observer.
    if (wrapper.dataset.standardGridOverlayScrollbar !== "1") {
      state.bodyHeightObserver = new ResizeObserver(() => updateScrollbarLane(state));
      state.bodyHeightObserver.observe(state.bodyTable);
    }
  }

}

export function upgradeStandardDataGrid(wrapper, explicitOptions = null) {
  if (!wrapper) return null;
  const ready = reuseReadyGrid(wrapper);
  if (ready) return ready;
  const options = explicitOptions || resolveOptions(wrapper);
  if (!options) return null;

  const table = directTable(wrapper);
  if (!table) return null;
  // DataGrid is a consumer, never a second Header generator. Resolve any static
  // schema marker through the canonical engine before the split shell is built.
  hydrateCanonicalColumnTitles(wrapper);
  const thead = table.querySelector(":scope > thead");
  const tbody = table.querySelector(":scope > tbody");
  const canonicalRow = thead?.querySelector(":scope > tr[data-canonical-title-row]");
  if (!thead || !tbody || !canonicalRow) return null;
  wrapper.dataset.standardGridTitleSource = "canonical";

  const state = buildGridShell(wrapper, table, tbody, options);
  if (rowSnapEnabled(wrapper)) {
    ensureGridRowSnap(state);
  }
  // Rows of different heights (an expandable record table, data-row-stops="1") rest on each shown row's top.
  if (wrapper.dataset.rowStops === "1") state.rowStops = new RowStopController({ viewport: state.bodyScroll }).mount();
  const { headerViewport, bodyScroll } = state;
  bodyScroll.addEventListener("scroll", () => {
    if (headerViewport.scrollLeft !== bodyScroll.scrollLeft) headerViewport.scrollLeft = bodyScroll.scrollLeft;
  }, { passive: true });

  if (options.xRail) state.xRail = mountHorizontalRail({ viewport: bodyScroll, host: state.wrapper, before: bodyScroll.nextSibling, observe: [state.bodyTable] });
  bindLiveColumnResize(state);
  observeGrid(state, tbody);
  // Once now, so a grid split while its block opens (an expanded row's trades) is measured at its final size; again
  // after the next layouts, for column widths that settle later.
  syncColumnsNow(state);
  requestAnimationFrame(() => {
    syncColumnsNow(state);
    requestAnimationFrame(() => syncColumnsNow(state));
  });
  return state;
}

export function applyStandardDataGrids(root = document) {
  const scope = root?.querySelectorAll ? root : document;
  const candidates = new Set();
  for (const rule of GRID_RULES) {
    scope.querySelectorAll(rule.selector).forEach((node) => candidates.add(node));
    if (scope.matches?.(rule.selector)) candidates.add(scope);
  }
  // History event/detail wrappers keep an explicit no-horizontal-scroll policy.
  candidates.forEach((wrapper) => upgradeStandardDataGrid(wrapper));
}

export function installStandardDataGridSystem(root) {
  const resolvedRoot = root || document.body;
  if (!resolvedRoot) return;

  applyStandardDataGrids(resolvedRoot);
  if (DATA_GRID_RUNTIME.observer && DATA_GRID_RUNTIME.observerRoot === resolvedRoot) return;
  DATA_GRID_RUNTIME.observer?.disconnect?.();
  DATA_GRID_RUNTIME.observerRoot = resolvedRoot;
  // Only what was added is scanned, once per frame -- never the whole root against every GRID_RULES selector
  // for any added element, one rAF per mutation batch. Rows a grid renders into its own
  // body (live quotes, ticks) are inside an upgraded grid and are skipped.
  const pending = new Set();
  let frame = 0;
  DATA_GRID_RUNTIME.observer = new MutationObserver((records) => {
    for (const record of records) {
      for (const node of record.addedNodes || []) {
        if (node?.nodeType !== 1) continue;
        const grid = node.parentElement?.closest?.('[data-standard-data-grid-ready="1"]');
        if (grid) {
          // A node put directly into a grid wrapper (its shell rebuilt) re-checks that grid. Deeper content is
          // skipped unless it brings tables of its own (an expanded row's detail): those are grids too.
          if (node.parentElement === grid) pending.add(grid);
          else if (node.classList.contains("table-wrap") || node.getElementsByClassName("table-wrap").length) pending.add(node);
          continue;
        }
        pending.add(node);
        // A table rendered into a wrapper after the page mounted, or its header filled in later, makes that wrapper
        // a grid now: the wrapper itself was scanned before it had a table and is not among the added nodes.
        const host = node.parentElement?.closest?.(GRID_WRAPPER_SELECTOR);
        if (host) pending.add(host);
      }
    }
    if (!pending.size || frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      const nodes = [...pending];
      pending.clear();
      for (const node of nodes) if (node.isConnected) applyStandardDataGrids(node);
    });
  });
  DATA_GRID_RUNTIME.observer.observe(resolvedRoot, { childList: true, subtree: true });
}

/**
 * An expandable record row (帳務 個股數據 / 每日明細 / 配對明細, 資料中心 dates and products) is a `<tr>` with the class
 * `record-expand-row`, `expanded` while open, whose first cell is this one: the caret at the cell's left edge, turned
 * down while the row is open, the label aligned as the table aligns its cells. `labelHtml` is already escaped. The row
 * itself is what a click opens and closes.
 */
export function expandCellHtml(labelHtml) {
  return `<td class="record-expand-cell"><span class="record-expand-caret" aria-hidden="true">›</span><span class="record-expand-label">${labelHtml}</span></td>`;
}

/**
 * The detail row under an expandable record row: one cell across the table on the detail background, holding
 * `contentHtml`. `className` and `attrs` name the page's own row (already escaped); `open: false` draws it hidden for a
 * page that toggles it in place. It carries [data-row-detail]: it belongs to the record row above it, not a record of its own.
 * The content sits in one block, `.record-expand-body` (recordExpandBody), which is what the expand motion
 * (expand_motion.js) opens and closes: a table row itself cannot change height.
 */
export function expandDetailRowHtml({ colspan, contentHtml = "", open = true, className = "", attrs = "" }) {
  return `<tr class="record-expand-detail${className ? ` ${className}` : ""}" data-row-detail${attrs ? ` ${attrs}` : ""}${open ? "" : " hidden"}><td colspan="${colspan}"><div class="record-expand-body">${contentHtml}</div></td></tr>`;
}

/** The animated block of a detail row drawn by expandDetailRowHtml, or null. */
export function recordExpandBody(detailRow) {
  return detailRow?.querySelector?.(":scope > td > .record-expand-body") || null;
}
